function binary_search(arr, n) {
  let lo = 0
  let hi = arr.length - 1

  do {
    const m = Math.floor((lo + hi) / 2)
    const v = arr[m]

    if (v === n) {
      return [m, v]
    } else if (v > n) {
      hi = m
    } else {
      lo = m + 1
    }
  } while (lo < hi)

  return -1
}

